(()=>{'use strict';const login=document.getElementById('login'),hq=document.getElementById('hq');document.getElementById('signin').onclick=()=>{login.classList.add('hidden');hq.classList.remove('hidden');sessionStorage.setItem('vc-hq-preview','1')};document.getElementById('logout').onclick=()=>{sessionStorage.removeItem('vc-hq-preview');hq.classList.add('hidden');login.classList.remove('hidden')};if(sessionStorage.getItem('vc-hq-preview')==='1'){login.classList.add('hidden');hq.classList.remove('hidden')}document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active')});})();